import{af as a,z as i,J as s,ab as t}from"./chunks/framework.C1QHhBQn.js";const u=JSON.parse('{"title":"Capabilities","description":"","frontmatter":{},"headers":[],"relativePath":"devices/capabilities/index.md","filePath":"devices/capabilities/index.md"}'),l={name:"devices/capabilities/index.md"};function r(d,e,n,o,c,p){return i(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794236815000"},[...e[0]||(e[0]=[t('<h1 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h1><p>Many of our devices share common capabilities. These capabilities are features that can be used across different devices, and integrate into various parts of our ecosystem, such as the Cloud App, APIs, and more.</p><p>Collected here for convenience.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Not all capabilities listed</p><p>We are building out this documentation section</p></div><h2 id="available-capabilities" tabindex="-1">Available capabilities <a class="header-anchor" href="#available-capabilities" aria-label="Permalink to &quot;Available capabilities&quot;">​</a></h2><ul><li><a href="./ble-scanning">BLE scanning</a></li><li><a href="./four-power-leds">Four power LEDs</a>: the reusable battery-bar and charging display.</li><li><a href="./gps-gsm-status-leds">GPS and GSM status LEDs</a>: the separate diagnostic pair found on some older devices.</li><li><a href="./rgb-status-leds">RGB status LEDs</a>: colour/brightness status displays, with model-specific meanings and overrides.</li></ul><p>A device page identifies which capabilities it has and describes its hardware-specific details. Capability pages define the shared feature and its limits. For help interpreting an unfamiliar pattern, use the <a href="/docs/pr/40/guides/leds">LED guide</a>.</p>',7)])])}const h=a(l,[["render",r]]);export{u as __pageData,h as default};
